// Some portions generated by Claude
/** Literal values read as dates, numbers and coordinates for the Timeline, Chart and Map views. */
import type { GraphEdge, GraphNode } from "./graph-types.ts";

const DATE_TYPES = /#(date|dateTime|dateTimeStamp|gYear|gYearMonth)$/;
const PLAIN_TYPES = /#(string|langString)$/;

/**
 * A literal as a date: values typed xsd:date, xsd:dateTime, xsd:gYear or xsd:gYearMonth, and plain strings that are
 * ISO dates ("1986-04-02"). Numbers such as 2001 are not dates unless they are typed as years.
 */
export function parseGraphDate(node: GraphNode) {
  if (node.kind !== "literal") return null;
  const raw = (node.termValue ?? node.label).trim();
  const datatype = node.datatype ?? "";
  const typed = DATE_TYPES.test(datatype);
  if (!typed && !((!datatype || PLAIN_TYPES.test(datatype)) && /^\d{4}-\d{2}-\d{2}/.test(raw))) return null;
  const text = /^-?\d{4}$/.test(raw) ? `${raw}-01-01T00:00:00Z` : /^\d{4}-\d{2}$/.test(raw) ? `${raw}-01T00:00:00Z` : /^\d{4}-\d{2}-\d{2}$/.test(raw) ? `${raw}T00:00:00Z` : raw;
  const date = new Date(text);
  return Number.isFinite(date.getTime()) ? date : null;
}

export function parseGraphNumber(node: GraphNode) {
  if (node.kind !== "literal") return null;
  const numeric = Number(node.termValue ?? node.label);
  return Number.isFinite(numeric) ? numeric : null;
}

export function parseGraphCoordinate(node: GraphNode) {
  if (node.kind !== "literal") return null;
  const match = (node.termValue ?? node.label).match(
    /Point\(\s*(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\s*\)/i,
  );
  if (!match) return null;
  const longitude = Number(match[1]);
  const latitude = Number(match[2]);
  return Number.isFinite(latitude) && Number.isFinite(longitude)
    ? { latitude, longitude }
    : null;
}

const GEO = "http://www.w3.org/2003/01/geo/wgs84_pos#";
const SCHEMA = ["http://schema.org/", "https://schema.org/"];
const LATITUDE = new Set([`${GEO}lat`, ...SCHEMA.map((namespace) => `${namespace}latitude`)]);
const LONGITUDE = new Set([`${GEO}long`, ...SCHEMA.map((namespace) => `${namespace}longitude`)]);
/** Links from a resource to the node that holds its coordinates (schema:geo GeoCoordinates, geo:location). */
const LOCATION = new Set([`${GEO}location`, ...SCHEMA.map((namespace) => `${namespace}geo`)]);

export type Place = { node: GraphNode; latitude: number; longitude: number; edgeIds: string[] };

/**
 * The loaded resources that have a position: a WKT point (geo:asWKT, Wikidata P625, …), or a latitude and a
 * longitude (geo:lat/geo:long, schema:latitude/schema:longitude), on the resource or on the node its schema:geo or
 * geo:location points at. One place per resource, in the order they were loaded.
 */
export function placesOf(edges: readonly GraphEdge[], nodeById: ReadonlyMap<string, GraphNode>): Place[] {
  const holders = new Map<string, { latitude?: number; longitude?: number; edgeIds: string[] }>();
  const owners = new Map<string, string>();
  const holder = (id: string) => {
    let entry = holders.get(id);
    if (!entry) holders.set(id, (entry = { edgeIds: [] }));
    return entry;
  };
  for (const edge of edges) {
    if (LOCATION.has(edge.predicate) && !owners.has(edge.target)) owners.set(edge.target, edge.source);
    const target = nodeById.get(edge.target);
    if (target?.kind !== "literal") continue;
    const point = parseGraphCoordinate(target);
    if (point) {
      const entry = holder(edge.source);
      entry.latitude = point.latitude;
      entry.longitude = point.longitude;
      entry.edgeIds.push(edge.id);
    } else if (LATITUDE.has(edge.predicate) || LONGITUDE.has(edge.predicate)) {
      const value = parseGraphNumber(target);
      if (value === null) continue;
      const entry = holder(edge.source);
      if (LATITUDE.has(edge.predicate)) entry.latitude = value;
      else entry.longitude = value;
      entry.edgeIds.push(edge.id);
    }
  }
  const places = new Map<string, Place>();
  for (const [holderId, { latitude, longitude, edgeIds }] of holders) {
    if (latitude === undefined || longitude === undefined) continue;
    if (Math.abs(latitude) > 90 || Math.abs(longitude) > 180) continue;
    const node = nodeById.get(owners.get(holderId) ?? holderId);
    if (node && !places.has(node.id)) places.set(node.id, { node, latitude, longitude, edgeIds });
  }
  return [...places.values()];
}

/** The map's bounds around every place: a tenth of the extent as margin, at least 0.2° across. */
export function mapFrame(places: ReadonlyArray<{ latitude: number; longitude: number }>) {
  const round = (value: number) => Math.round(value * 10000) / 10000;
  const bounds = (values: number[], limit: number) => {
    const low = Math.min(...values);
    const high = Math.max(...values);
    const margin = Math.max((high - low) / 10, (0.2 - (high - low)) / 2, 0);
    return [round(Math.max(-limit, low - margin)), round(Math.min(limit, high + margin))];
  };
  const [south, north] = bounds(places.map((place) => place.latitude), 90);
  const [west, east] = bounds(places.map((place) => place.longitude), 180);
  return { west, south, east, north };
}
